def norm(ep: str) -> str:
    return re.sub(r"(:([A-Za-z0-9_]+)|\{([A-Za-z0-9_]+)\}|<(?:[A-Za-z0-9_]+:)?([A-Za-z0-9_]+)>)", "{param}", ep.strip())


names = [f["name"] for f in bp["lambda_functions"]]
pkg_eps = {pkg["id"]: {norm("{} {}".format(e["method"], e["path"])) for e in pkg["endpoints"]}
           for pkg in data["packages"]}
fn_eps = {f["name"]: {norm(e) for e in (f.get("entry_points") or [])} for f in bp["lambda_functions"]}

assigned = {pid: [n for n in names if fn_eps[n] and (fn_eps[n] & eps)] for pid, eps in pkg_eps.items()}

